  MyPolitikTranslations.tambah([
  ["Satu misi baharu setiap bulan. Rentetan", "One new mission every month. A streak of"],
  ["bulan berturut-turut memberi bonus. Bulan terlepas hanya memutuskan rentetan.", "consecutive months gives a bonus. A missed month only breaks the streak."],
  ["Kebolehan istimewa sayap anda. Boleh digunakan", "Your wing's special ability. Can be used"], ["sekali sebulan", "once a month"],
  ["+30 IP, -MYR 500, -3 AP, +1 Reputasi Parti, +4 Sokongan Akar Umbi, Stress +10 (risiko 30%)", "+30 IP, -MYR 500, -3 AP, +1 Party Reputation, +4 Grassroots Support, Stress +10 (30% risk)"],
  ["{n} bulan lagi · kawasan {k}. Kelayakan: DUN {a} (IP {b} + jawatan), Parlimen {c} (IP {d} + Ketua Bahagian).", "{n} months left · area {k}. Eligibility: DUN {a} (IP {b} + post), Parliament {c} (IP {d} + Division Chief)."],
  ["Sayap", "Wing"], ["Sayap Pemuda", "Pemuda Wing"], ["Sayap Puteri", "Puteri Wing"], ["Sayap Wanita", "Wanita Wing"],
  ["Pemilihan Sayap Cawangan", "Wing Branch Election"], ["Pemilihan Sayap Bahagian", "Wing Division Election"], ["Pemilihan Sayap Pusat", "Wing Central Election"],
  ["Bulan 4-5 · Ketua, Naib Ketua dan AJK Sayap Cawangan (tahun pemilihan) dan wakil sayap ke Mesyuarat Perwakilan Sayap Bahagian (laluan sayap sahaja). Hanya satu jawatan bagi setiap peringkat boleh dipegang (jika kedua-dua jawatan utama dan sayap dimenangi, yang lebih tinggi dikekalkan); perwakilan dipertandingkan bersama.", "Months 4-5 · Wing Branch Chief, Deputy Chief and AJK (election year) and wing delegates to the Wing Division Delegates Meeting (wing path only). Only one post per level can be held (if both the main and wing posts are won, the higher is kept); delegates are contested together."],
  ["Bulan 6 · Ketua, Naib Ketua dan AJK Sayap Bahagian (tahun pemilihan), G10 (10 wakil) ke Mesyuarat Perwakilan Bahagian dan G2 (2 wakil) ke Perhimpunan Sayap Pusat. Hanya satu jawatan bagi setiap peringkat boleh dipegang (jika kedua-dua jawatan utama dan sayap dimenangi, yang lebih tinggi dikekalkan); perwakilan dipertandingkan bersama.", "Month 6 · Wing Division Chief, Deputy Chief and AJK (election year), G10 (10 delegates) to the Division Delegates Meeting and G2 (2 delegates) to the Central Wing Assembly. Only one post per level can be held (if both the main and wing posts are won, the higher is kept); delegates are contested together."],
  ["Bulan 9 · Ketua, Naib Ketua dan AJK Sayap Pusat, dipilih dalam Perhimpunan Sayap (Pra-PAU), laluan sayap sahaja. Hanya satu jawatan bagi setiap peringkat boleh dipegang (jika kedua-dua jawatan utama dan sayap dimenangi, yang lebih tinggi dikekalkan); perwakilan dipertandingkan bersama.", "Month 9 · Central Wing Chief, Deputy Chief and AJK, elected at the Wing Assembly (Pre-PAU), wing path only. Only one post per level can be held (if both the main and wing posts are won, the higher is kept); delegates are contested together."],
  ["Persidangan Tahunan {w} Cawangan dibuka pada bulan 4-5. Sekarang bulan {n}. Anda layak hadir.", "The {w} Branch Annual Conference opens in months 4-5. It is now month {n}. You are eligible to attend."],
  ["Hanya wakil {w} Cawangan tahun {y} yang terpilih, Ketua {w} Cawangan dan pemegang jawatan Bahagian/Pusat boleh hadir Mesyuarat Perwakilan {w} Bahagian.", "Only {w} Branch delegates elected for {y}, the {w} Branch Chief and Division/Central post-holders can attend the {w} Division Delegates Meeting."],
  ["Hanya G2 {w} (2 wakil Bahagian) tahun {y}, Ketua {w} Bahagian, Ketua Bahagian dan pemegang jawatan Pusat boleh hadir Perhimpunan {w} Pusat.", "Only the {w} G2 (2 Division delegates) for {y}, the {w} Division Chief, Division Chief and Central post-holders can attend the {w} Central Assembly."],
  ["Latihan Bersama Amir", "Training with Amir"], ["Latihan bersama Amir", "Training with Amir"], ["Mula Latihan Bersama Amir", "Start Training with Amir"],
  ["Asas Permainan", "Game Basics"], ["Peranan Sayap", "Wing Roles"], ["Struktur Organisasi & Mesyuarat Sayap", "Organisation Structure & Wing Meetings"],
  ["PRU/PRN, Kempen & Kabinet", "GE/State Elections, Campaigns & Cabinet"], ["Dewan Rakyat & Usul Parlimen", "Dewan Rakyat & Parliamentary Motions"],
  ["Sampingan, Anugerah & Gelaran", "Side Hustles, Awards & Titles"], ["Krisis & Dilema Kepimpinan", "Crises & Leadership Dilemmas"],
  ["Umur & Kesihatan", "Age & Health"], ["Tataetika & Disiplin", "Code of Ethics & Discipline"], ["Gaya Kepimpinan", "Leadership Style"],
  ["Cara terbaik belajar ialah dengan bermain.", "The best way to learn is by playing."],
  ["ialah permainan contoh berpandu (kira-kira 10 minit): daripada ahli biasa cawangan, ke pemilihan, mesyuarat, PRU, Kabinet dan PRK, hingga", "is a guided sample game (about 10 minutes): from a regular branch member, through elections, meetings, GE, Cabinet and by-elections, to the"],
  ["Pemandu menyorot butang yang perlu ditekan. Anda boleh tekan", "The guide highlights the button to press. You can press"],
  ["di tab Tindakan. AP bertambah 5 setiap bulan dan baki dibawa sehingga had 15, jadi jangan biarkan AP penuh.", "in the Actions tab. AP increases by 5 each month and the balance carries over up to the cap of 15, so do not let AP sit full."],
  ["tab Pemilihan, Mesyuarat dan 📣 Pilihan Raya (muncul sendiri semasa musim pilihan raya).", "the Elections, Meetings and 📣 General Election tabs (they appear on their own during the election season)."],
  ["; jawab acara, krisis atau dilema yang muncul.", "; answer any event, crisis or dilemma that comes up."]
  ]);
